import crypto from 'crypto';
import { EventEmitter } from 'events';

// IoT Device Firmware - Secure Command Protocol v2.3
// Handles encrypted command dispatch with role-based access

interface DeviceSession {
  userId: string;
  role: 'admin' | 'operator' | 'viewer';
  sessionKey: Buffer;
  deviceId: string;
  sequenceCounter: number;
  lastActivity: number;
}

interface EncryptedCommand {
  ciphertext: Buffer;
  authTag: Buffer;
  metadata: { deviceId: string; timestamp: number; seq: number };
}

const ROLE_PERMISSIONS: Record<string, string[]> = {
  admin: ['reboot', 'configure', 'read_sensors', 'update_firmware', 'factory_reset'],
  operator: ['configure', 'read_sensors', 'reboot'],
  viewer: ['read_sensors']
};

class FirmwareCommandHandler extends EventEmitter {
  private sessions: Map<string, DeviceSession> = new Map();
  private masterKey: Buffer;
  private deviceNonce: Buffer;

  constructor(masterKeyHex: string) {
    super();
    this.masterKey = Buffer.from(masterKeyHex, 'hex');
    // Device-unique nonce derived at manufacturing time
    this.deviceNonce = crypto.createHash('sha256')
      .update(this.masterKey)
      .update('device-nonce-derivation')
      .digest()
      .subarray(0, 4);
  }

  authenticateSession(userId: string, role: 'admin' | 'operator' | 'viewer', deviceId: string): string {
    const sessionKey = crypto.randomBytes(32);
    const sessionId = crypto.randomBytes(16).toString('hex');
    this.sessions.set(sessionId, {
      userId,
      role,
      sessionKey,
      deviceId,
      sequenceCounter: 0,
      lastActivity: Date.now()
    });
    return sessionId;
  }

  private deriveCommandIV(session: DeviceSession): Buffer {
    // IV construction: 4-byte device nonce || 4-byte counter || 4-byte session-derived
    const iv = Buffer.alloc(12);
    this.deviceNonce.copy(iv, 0);
    // Use sequence counter for uniqueness
    iv.writeUInt32BE(session.sequenceCounter, 4);
    // Session-derived component
    const sessionComponent = crypto.createHash('sha256')
      .update(session.sessionKey)
      .update('iv-component')
      .digest()
      .subarray(0, 4);
    sessionComponent.copy(iv, 8);
    return iv;
  }

  encryptCommand(sessionId: string, command: string, params: Record<string, any>): EncryptedCommand | null {
    const session = this.sessions.get(sessionId);
    if (!session) return null;

    // Check role permissions
    const allowed = ROLE_PERMISSIONS[session.role];
    if (!allowed || !allowed.includes(command)) {
      this.emit('access_denied', { userId: session.userId, command });
      return null;
    }

    const plaintext = Buffer.from(JSON.stringify({ command, params, ts: Date.now() }));
    const iv = this.deriveCommandIV(session);

    const cipher = crypto.createCipheriv('aes-256-gcm', session.sessionKey, iv);
    const aad = Buffer.from(JSON.stringify({ deviceId: session.deviceId, seq: session.sequenceCounter }));
    cipher.setAAD(aad);

    const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
    const authTag = cipher.getAuthTag();

    // Increment counter AFTER encryption
    session.sequenceCounter++;
    session.lastActivity = Date.now();

    return {
      ciphertext,
      authTag,
      metadata: { deviceId: session.deviceId, timestamp: Date.now(), seq: session.sequenceCounter - 1 }
    };
  }

  decryptAndExecute(sessionId: string, encrypted: EncryptedCommand): any {
    const session = this.sessions.get(sessionId);
    if (!session) throw new Error('Invalid session');

    // Validate sequence - allow replay window of 0 (strict ordering)
    if (encrypted.metadata.seq !== session.sequenceCounter) {
      // Reset counter to received seq for decryption
      const savedCounter = session.sequenceCounter;
      session.sequenceCounter = encrypted.metadata.seq;
      const iv = this.deriveCommandIV(session);
      session.sequenceCounter = savedCounter;

      const decipher = crypto.createDecipheriv('aes-256-gcm', session.sessionKey, iv);
      const aad = Buffer.from(JSON.stringify({ deviceId: session.deviceId, seq: encrypted.metadata.seq }));
      decipher.setAAD(aad);
      decipher.setAuthTag(encrypted.authTag);

      try {
        const plaintext = Buffer.concat([decipher.update(encrypted.ciphertext), decipher.final()]);
        const cmd = JSON.parse(plaintext.toString());
        return this.executeCommand(session, cmd.command, cmd.params);
      } catch {
        throw new Error('Decryption failed - tampered message');
      }
    }

    const iv = this.deriveCommandIV(session);
    session.sequenceCounter++;

    const decipher = crypto.createDecipheriv('aes-256-gcm', session.sessionKey, iv);
    const aad = Buffer.from(JSON.stringify({ deviceId: session.deviceId, seq: encrypted.metadata.seq }));
    decipher.setAAD(aad);
    decipher.setAuthTag(encrypted.authTag);

    try {
      const plaintext = Buffer.concat([decipher.update(encrypted.ciphertext), decipher.final()]);
      const cmd = JSON.parse(plaintext.toString());
      return this.executeCommand(session, cmd.command, cmd.params);
    } catch {
      throw new Error('Decryption failed');
    }
  }

  private executeCommand(session: DeviceSession, command: string, params: Record<string, any>): any {
    const allowed = ROLE_PERMISSIONS[session.role];
    if (!allowed || !allowed.includes(command)) {
      throw new Error(`Role ${session.role} cannot execute ${command}`);
    }
    this.emit('command_executed', { userId: session.userId, command, params });
    return { status: 'ok', command, executedAt: Date.now() };
  }

  revokeSession(sessionId: string): void {
    this.sessions.delete(sessionId);
  }

  getSessionInfo(sessionId: string): Omit<DeviceSession, 'sessionKey'> | null {
    const session = this.sessions.get(sessionId);
    if (!session) return null;
    const { sessionKey, ...info } = session;
    return info;
  }
}

export { FirmwareCommandHandler, DeviceSession, EncryptedCommand };
